<?php require_once '../config/db.php'; require_once '../includes/auth.php'; require_role('faculty');$rows=$pdo->query("SELECT s.*,COUNT(u.id) unit_count FROM subjects s LEFT JOIN units u ON u.subject_id=s.id GROUP BY s.id ORDER BY s.name")->fetchAll();$page_title='Subjects';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='faculty';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Subjects</h1><div class="table-card"><table><thead><tr><th>Subject</th><th>Course</th><th>Year</th><th>Semester</th><th>Units</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['course'])?></td><td><?=e($r['year'])?></td><td><?=e($r['semester'])?></td><td><?=$r['unit_count']?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>